public record WorkItem(
    int id,
    String label,
    long durationMillis
) {
  public WorkItem {
    if (durationMillis < 0) {
      throw new IllegalArgumentException("Durée négative");
    }
  }
}

public record WorkResult(
    int taskId,
    boolean success,
    String message,
    long elapsedMillis
) {}

static WorkResult process(WorkItem item) {
  long start = System.nanoTime();
  try {
    Thread.sleep(item.durationMillis());
    return new WorkResult(item.id(), true, "Terminé", elapsed(start));
  } catch (InterruptedException error) {
    Thread.currentThread().interrupt();
    return new WorkResult(item.id(), false, "Interrompu", elapsed(start));
  }
}

ExecutorService executor = Executors.newFixedThreadPool(3);
List<CompletableFuture<WorkResult>> futures = items.stream()
    .map(item -> CompletableFuture.supplyAsync(
        () -> process(item), executor
    ))
    .toList();

List<WorkResult> results = futures.stream()
    .map(CompletableFuture::join)
    .toList();
long successCount = results.stream()
    .filter(WorkResult::success)
    .count();

long globalStart = System.nanoTime();
try {
  // soumettre et rassembler les tâches
  System.out.println("Succès : " + successCount);
} finally {
  executor.shutdown();
  System.out.println("Durée : " + elapsed(globalStart) + " ms");
}
